for k, v in pairs(tbl) do
	v.AllowChat = true

	if not v.Image and v.Price < 0 then
		v.ChatLocked = true
		v.DefaultSticker = true
	end

	if v.Chat == "" or v.Text == "" then
		v.AllowChat = false
		v.ChatLocked = true
	end
end

return tbl